<?php declare(strict_types=1); $types=['stock_bajo'=>'Stock bajo','sin_stock'=>'Sin existencias','proximo_vencimiento'=>'Próximo a vencer','vencido'=>'Vencido']; $statuses=['activa'=>'Activa','atendida'=>'Atendida','descartada'=>'Descartada']; ?>
<section>
 <div class="mb-6"><p class="text-sm font-semibold uppercase tracking-wide text-emerald-700">Control preventivo</p><h1 class="mt-1 text-3xl font-bold text-slate-900">Alertas de inventario</h1><p class="mt-2 text-sm text-slate-600">Se actualizan al abrir esta pantalla. Los lotes próximos a vencer son los que vencen en los siguientes 30 días.</p></div>
 <?php foreach (['success'=>'emerald','error'=>'red'] as $key=>$color): if ($message=flash($key)): ?><div class="mb-4 rounded-lg bg-<?= e($color) ?>-50 p-3 text-sm"><?= e($message) ?></div><?php endif; endforeach; ?>
 <form class="mb-5 flex flex-wrap items-end gap-3 rounded-xl border bg-white p-4" method="get" action="<?= e($baseUrl) ?>/alertas"><label class="text-xs font-semibold">Estado<select name="estado" class="mt-1 block min-h-10 rounded-lg border px-3 text-sm"><option value="">Todos</option><?php foreach($statuses as $key=>$label): ?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="min-h-10 rounded-lg bg-emerald-700 px-4 text-sm font-semibold text-white">Filtrar</button></form>
 <div class="overflow-x-auto rounded-xl border bg-white"><table class="min-w-full divide-y text-left text-sm"><thead class="bg-slate-50 text-xs uppercase"><tr><?php foreach(['Tipo','Producto / lote','Detalle','Estado','Fecha','Acciones'] as $h): ?><th class="px-4 py-3"><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y">
 <?php if (!$rows): ?><tr><td colspan="6" class="px-4 py-10 text-center text-slate-500">No hay alertas para mostrar.</td></tr><?php endif; ?>
 <?php foreach($rows as $row): ?><tr><td class="px-4 py-3 font-semibold"><?= e($types[$row['tipo']]??$row['tipo']) ?></td><td class="px-4 py-3"><?= e($row['producto']) ?><div class="text-xs text-slate-500"><?= e($row['codigo']) ?><?= $row['codigo_lote']?' · Lote '.e($row['codigo_lote']):'' ?></div></td><td class="px-4 py-3"><?= e($row['mensaje']) ?></td><td class="px-4 py-3"><?= e($statuses[$row['estado']]??$row['estado']) ?></td><td class="whitespace-nowrap px-4 py-3"><?= e(date('d/m/Y H:i',strtotime($row['creada_en']))) ?></td><td class="px-4 py-3"><div class="flex gap-2"><?php if($row['estado']==='activa' && can('alertas.atender')): ?><form method="post" action="<?= e($baseUrl) ?>/alertas/atender"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="rounded border px-2 py-1">Atender</button></form><?php endif; ?><?php if($row['estado']==='activa' && can('alertas.descartar')): ?><form method="post" action="<?= e($baseUrl) ?>/alertas/descartar"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="rounded border px-2 py-1">Descartar</button></form><?php endif; ?></div></td></tr><?php endforeach; ?>
 </tbody></table></div>
</section>
